CREATE TABLE tokens (name TEXT PRIMARY KEY, generation INTEGER NOT NULL);
INSERT INTO "tokens" VALUES('browser',1);
CREATE INDEX pendings_waiting ON pendings (state, expires_at);
CREATE INDEX labels_lookup ON labels (resource_key, field, value_sha256);
CREATE INDEX effects_applied ON effects (applied_at DESC, operation_id, idx) WHERE status = 'APPLIED';
CREATE TRIGGER label_rev_on_label AFTER INSERT ON labels BEGIN UPDATE meta SET value = CAST(CAST(value AS INTEGER) + 1 AS TEXT) WHERE key = 'label_rev'; END;
CREATE TRIGGER label_rev_on_authority AFTER INSERT ON authority_log BEGIN UPDATE meta SET value = CAST(CAST(value AS INTEGER) + 1 AS TEXT) WHERE key = 'label_rev'; END;
CREATE TRIGGER label_rev_on_meta_insert AFTER INSERT ON meta WHEN NEW.key IN ('epoch', 'install_class') BEGIN UPDATE meta SET value = CAST(CAST(value AS INTEGER) + 1 AS TEXT) WHERE key = 'label_rev'; END;
CREATE TRIGGER label_rev_on_meta_update AFTER UPDATE ON meta WHEN NEW.key IN ('epoch', 'install_class') OR OLD.key IN ('epoch', 'install_class') BEGIN UPDATE meta SET value = CAST(CAST(value AS INTEGER) + 1 AS TEXT) WHERE key = 'label_rev'; END;
CREATE TRIGGER label_rev_rises BEFORE UPDATE ON meta WHEN OLD.key = 'label_rev' BEGIN SELECT RAISE(ABORT, 'meta.label_rev only rises, as a canonical integer') WHERE NEW.key IS NOT 'label_rev' OR typeof(NEW.value) IS NOT 'text' OR CAST(NEW.value AS INTEGER) || '' IS NOT NEW.value OR CAST(NEW.value AS INTEGER) <= CAST(OLD.value AS INTEGER); END;
CREATE TRIGGER meta_keeps_its_authority BEFORE DELETE ON meta WHEN OLD.key IN ('epoch', 'install_class', 'label_rev') BEGIN SELECT RAISE(ABORT, 'meta epoch, install_class and label_rev are never deleted'); END;
CREATE TRIGGER labels_immutable_update BEFORE UPDATE ON labels BEGIN SELECT RAISE(ABORT, 'a label row is immutable'); END;
CREATE TRIGGER labels_immutable_delete BEFORE DELETE ON labels BEGIN SELECT RAISE(ABORT, 'a label row is immutable'); END;
CREATE TRIGGER pendings_authority_immutable BEFORE UPDATE ON pendings WHEN NEW.record IS NOT OLD.record OR NEW.record_sha256 IS NOT OLD.record_sha256 OR (OLD.decision_kind IS NOT NULL AND NEW.decision_kind IS NOT OLD.decision_kind) OR (OLD.signer_fp IS NOT NULL AND NEW.signer_fp IS NOT OLD.signer_fp) OR (OLD.credential IS NOT NULL AND NEW.credential IS NOT OLD.credential) OR (OLD.decided_at IS NOT NULL AND NEW.decided_at IS NOT OLD.decided_at) BEGIN SELECT RAISE(ABORT, 'a pending''s record and decision are written once'); END;
COMMIT;
